const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, HeadingLevel,
  LevelFormat, VerticalAlign, PageNumber, Header, Footer, TabStopType,
  TabStopPosition
} = require('docx');
const fs = require('fs');

// Colors
const GOLD = "C9A84C";
const DARK = "1A1A2E";
const LIGHT_GOLD = "F9F3E8";
const MED_GOLD = "EFD99A";
const WHITE = "FFFFFF";
const GRAY = "F5F5F5";
const MED_GRAY = "DDDDDD";
const DARK_GRAY = "555555";
const CHECK_BOX = "\u25A1"; // empty checkbox

function cellBorder(color = MED_GRAY) {
  const b = { style: BorderStyle.SINGLE, size: 1, color };
  return { top: b, bottom: b, left: b, right: b };
}

function noBorder() {
  const b = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
  return { top: b, bottom: b, left: b, right: b };
}

function sectionHeader(text) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: noBorder(),
            shading: { fill: DARK, type: ShadingType.CLEAR },
            margins: { top: 140, bottom: 140, left: 180, right: 180 },
            width: { size: 9360, type: WidthType.DXA },
            children: [
              new Paragraph({
                alignment: AlignmentType.LEFT,
                children: [
                  new TextRun({
                    text,
                    bold: true,
                    color: WHITE,
                    font: "Arial",
                    size: 24,
                  })
                ]
              })
            ]
          })
        ]
      })
    ]
  });
}

function callHeader(callNum, phase, dateRange) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [6000, 3360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: noBorder(),
            shading: { fill: GOLD, type: ShadingType.CLEAR },
            margins: { top: 140, bottom: 140, left: 200, right: 200 },
            width: { size: 6000, type: WidthType.DXA },
            children: [
              new Paragraph({
                children: [
                  new TextRun({ text: `Call ${callNum}: ${phase}`, bold: true, font: "Arial", size: 26, color: DARK }),
                ]
              })
            ]
          }),
          new TableCell({
            borders: noBorder(),
            shading: { fill: MED_GOLD, type: ShadingType.CLEAR },
            margins: { top: 140, bottom: 140, left: 200, right: 200 },
            width: { size: 3360, type: WidthType.DXA },
            verticalAlign: VerticalAlign.CENTER,
            children: [
              new Paragraph({
                alignment: AlignmentType.RIGHT,
                children: [
                  new TextRun({ text: dateRange, font: "Arial", size: 20, color: DARK }),
                ]
              })
            ]
          })
        ]
      })
    ]
  });
}

function checkRow(label, detail = null) {
  const children = [
    new TextRun({ text: `${CHECK_BOX}  `, font: "Arial", size: 20, color: GOLD }),
    new TextRun({ text: label, font: "Arial", size: 20, color: DARK }),
  ];
  if (detail) {
    children.push(new TextRun({ text: `  ${detail}`, font: "Arial", size: 18, color: DARK_GRAY, italics: true }));
  }
  return new Paragraph({
    spacing: { before: 60, after: 60 },
    indent: { left: 180 },
    children
  });
}

function subLabel(text) {
  return new Paragraph({
    spacing: { before: 120, after: 40 },
    indent: { left: 180 },
    children: [
      new TextRun({ text, font: "Arial", size: 19, bold: true, color: DARK })
    ]
  });
}

function noteRow(label) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [2200, 7160],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: cellBorder(MED_GRAY),
            shading: { fill: GRAY, type: ShadingType.CLEAR },
            margins: { top: 80, bottom: 80, left: 120, right: 120 },
            width: { size: 2200, type: WidthType.DXA },
            children: [
              new Paragraph({
                children: [new TextRun({ text: label, font: "Arial", size: 18, bold: true, color: DARK_GRAY })]
              })
            ]
          }),
          new TableCell({
            borders: cellBorder(MED_GRAY),
            shading: { fill: WHITE, type: ShadingType.CLEAR },
            margins: { top: 80, bottom: 80, left: 120, right: 120 },
            width: { size: 7160, type: WidthType.DXA },
            children: [
              new Paragraph({ children: [new TextRun({ text: " ", font: "Arial", size: 18 })] })
            ]
          })
        ]
      })
    ]
  });
}

function tempCheck() {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [2340, 2340, 2340, 2340],
    rows: [
      new TableRow({
        children: ["Excited", "On Track", "Feeling Behind", "Struggling"].map((label, i) => {
