const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, BorderStyle, WidthType, ShadingType, LevelFormat,
  VerticalAlign, PageBreak
} = require('docx');
const fs = require('fs');

const GOLD = "C9A84C";
const DARK = "1A1A2E";
const LIGHT_GOLD = "F9F3E8";
const MED_GOLD = "EFD99A";
const WHITE = "FFFFFF";
const GRAY = "F5F5F5";
const MED_GRAY = "DDDDDD";
const DARK_GRAY = "666666";
const CHECK = "\u25A1";

function noBorder() {
  const b = { style: BorderStyle.NONE, size: 0, color: "FFFFFF" };
  return { top: b, bottom: b, left: b, right: b };
}
function border(color = MED_GRAY) {
  const b = { style: BorderStyle.SINGLE, size: 1, color };
  return { top: b, bottom: b, left: b, right: b };
}

function sp(pts = 120) {
  return new Paragraph({ spacing: { before: pts, after: 0 }, children: [new TextRun("")] });
}

function divider() {
  return new Paragraph({
    spacing: { before: 200, after: 200 },
    border: { bottom: { style: BorderStyle.SINGLE, size: 6, color: MED_GOLD, space: 1 } },
    children: [new TextRun("")]
  });
}

function callBanner(num, title, timing) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [5800, 3560],
    rows: [new TableRow({
      children: [
        new TableCell({
          borders: noBorder(),
          shading: { fill: DARK, type: ShadingType.CLEAR },
          margins: { top: 160, bottom: 160, left: 240, right: 240 },
          width: { size: 5800, type: WidthType.DXA },
          children: [
            new Paragraph({ children: [new TextRun({ text: `BIWEEKLY CALL #${num}`, font: "Arial", size: 18, color: GOLD, bold: true })] }),
            new Paragraph({ spacing: { before: 40 }, children: [new TextRun({ text: title, font: "Arial", size: 28, color: WHITE, bold: true })] }),
          ]
        }),
        new TableCell({
          borders: noBorder(),
          shading: { fill: GOLD, type: ShadingType.CLEAR },
          margins: { top: 160, bottom: 160, left: 200, right: 200 },
          width: { size: 3560, type: WidthType.DXA },
          verticalAlign: VerticalAlign.CENTER,
          children: [
            new Paragraph({ alignment: AlignmentType.CENTER, children: [new TextRun({ text: timing, font: "Arial", size: 20, color: DARK, bold: true })] })
          ]
        })
      ]
    })]
  });
}

function sectionBar(text) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [new TableRow({
      children: [new TableCell({
        borders: noBorder(),
        shading: { fill: MED_GOLD, type: ShadingType.CLEAR },
        margins: { top: 100, bottom: 100, left: 200, right: 200 },
        width: { size: 9360, type: WidthType.DXA },
        children: [new Paragraph({ children: [new TextRun({ text: text.toUpperCase(), font: "Arial", size: 20, bold: true, color: DARK })] })]
      })]
    })]
  });
}

function check(label, sub = null) {
  const kids = [
    new TextRun({ text: `${CHECK}  `, font: "Arial", size: 20, color: GOLD }),
    new TextRun({ text: label, font: "Arial", size: 20, color: DARK }),
  ];
  if (sub) kids.push(new TextRun({ text: `  ${sub}`, font: "Arial", size: 18, color: DARK_GRAY, italics: true }));
  return new Paragraph({ spacing: { before: 60, after: 60 }, indent: { left: 200 }, children: kids });
}

function noteField(label) {
  return new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [2400, 6960],
    rows: [new TableRow({
      children: [
        new TableCell({
          borders: border(MED_GRAY),
          shading: { fill: GRAY, type: ShadingType.CLEAR },
          margins: { top: 80, bottom: 80, left: 140, right: 140 },
